const fs = require('fs');
const https = require('https');

function fetchData(callback) {
  https.get('https://api.example.com/users', (res) => {
    let userData = '';
    res.on('data', (chunk) => userData += chunk);
    res.on('end', () => {
      https.get('https://api.example.com/posts', (res) => {
        let postData = '';
        res.on('data', (chunk) => postData += chunk);
        res.on('end', () => {
          const combined = JSON.stringify({
            users: JSON.parse(userData),
            posts: JSON.parse(postData)
          });
          fs.writeFile('output.json', combined, (err) => {
            if (err) return callback(err);
            callback(null, 'Data saved successfully');
          });
        });
      });
    });
  });
}

